CREATE TABLE bo3_series (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contract text NOT NULL DEFAULT 'match-v2-bo3' CHECK(contract='match-v2-bo3'), difficulty text NOT NULL CHECK(difficulty IN ('beginner','normal','historical')),
 dataset_version text NOT NULL, comparison_rules_version text NOT NULL DEFAULT 'v3' CHECK(comparison_rules_version='v3'), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','finished')),
 round_number integer NOT NULL DEFAULT 1 CHECK(round_number BETWEEN 1 AND 7), wins0 integer NOT NULL DEFAULT 0 CHECK(wins0 BETWEEN 0 AND 2), wins1 integer NOT NULL DEFAULT 0 CHECK(wins1 BETWEEN 0 AND 2), winner_slot integer CHECK(winner_slot IN (0,1)), revision integer NOT NULL DEFAULT 1 CHECK(revision>0), event_seq integer NOT NULL DEFAULT 0 CHECK(event_seq>=0),
 next_transition_at timestamptz, starts_at timestamptz NOT NULL, ended_at timestamptz, commitment text NOT NULL CHECK(commitment~'^[a-f0-9]{64}$'), sealed_seed text NOT NULL, seed_context jsonb NOT NULL, algorithm_version text NOT NULL DEFAULT 'bo3-seed-v1' CHECK(algorithm_version='bo3-seed-v1'), answer_driver_ids text[] NOT NULL CHECK(cardinality(answer_driver_ids)=7),
 UNIQUE(id,dataset_version), FOREIGN KEY(dataset_version,comparison_rules_version) REFERENCES dataset_versions(version,rules_version),
 CHECK((status='active' AND ended_at IS NULL AND winner_slot IS NULL AND next_transition_at IS NOT NULL) OR (status='finished' AND ended_at IS NOT NULL AND winner_slot IS NOT NULL AND next_transition_at IS NULL AND ended_at>=starts_at))
);
CREATE INDEX bo3_due_idx ON bo3_series(next_transition_at,id) WHERE status='active';
--> statement-breakpoint
CREATE TABLE bo3_players (series_id uuid NOT NULL REFERENCES bo3_series(id),principal_id uuid NOT NULL REFERENCES identity_principals(id),slot integer NOT NULL CHECK(slot IN (0,1)),public_label uuid NOT NULL,PRIMARY KEY(series_id,principal_id),UNIQUE(series_id,slot),UNIQUE(series_id,public_label));
CREATE TABLE bo3_memberships(principal_id uuid PRIMARY KEY REFERENCES identity_principals(id),series_id uuid NOT NULL,FOREIGN KEY(series_id,principal_id) REFERENCES bo3_players(series_id,principal_id));
CREATE TABLE bo3_queue(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),principal_id uuid NOT NULL REFERENCES identity_principals(id),difficulty text NOT NULL CHECK(difficulty IN ('beginner','normal','historical')),position bigint GENERATED ALWAYS AS IDENTITY UNIQUE,created_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','matched','cancelled','expired')),series_id uuid REFERENCES bo3_series(id),CHECK(expires_at=created_at+interval '120 seconds'),CHECK((status='matched')=(series_id IS NOT NULL)));
CREATE UNIQUE INDEX bo3_queue_one_queued ON bo3_queue(principal_id) WHERE status='queued';
CREATE INDEX bo3_queue_pair_idx ON bo3_queue(difficulty,position) WHERE status='queued';
--> statement-breakpoint
CREATE TABLE bo3_rounds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),series_id uuid NOT NULL,round_number integer NOT NULL CHECK(round_number BETWEEN 1 AND 7),answer_driver_id text NOT NULL,dataset_version text NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','revealed')),starts_at timestamptz NOT NULL,deadline_at timestamptz NOT NULL,effective_ended_at timestamptz,result_until timestamptz,winner_slot integer CHECK(winner_slot IN (0,1)),reason text CHECK(reason IN ('correct','surrender','exhausted','deadline','disconnect','score','seed')),UNIQUE(series_id,round_number),UNIQUE(series_id,answer_driver_id),UNIQUE(id,series_id),UNIQUE(id,dataset_version),FOREIGN KEY(series_id,dataset_version) REFERENCES bo3_series(id,dataset_version),FOREIGN KEY(answer_driver_id,dataset_version) REFERENCES driver_stats(driver_id,dataset_version),CHECK(deadline_at=starts_at+interval '480 seconds'),CHECK((status='active' AND effective_ended_at IS NULL AND result_until IS NULL AND winner_slot IS NULL AND reason IS NULL) OR (status='revealed' AND effective_ended_at>=starts_at AND effective_ended_at<=deadline_at AND result_until=effective_ended_at+interval '5 seconds' AND reason IS NOT NULL AND (round_number<7 OR winner_slot IS NOT NULL))));
CREATE TABLE bo3_round_players(round_id uuid NOT NULL,series_id uuid NOT NULL,principal_id uuid NOT NULL,attempts_used integer NOT NULL DEFAULT 0 CHECK(attempts_used BETWEEN 0 AND 8),last_heartbeat_at timestamptz NOT NULL,lease_expires_at timestamptz NOT NULL,highest_score integer NOT NULL DEFAULT 0 CHECK(highest_score BETWEEN 0 AND 16),first_best_attempt integer NOT NULL DEFAULT 9 CHECK(first_best_attempt BETWEEN 1 AND 9),total_score integer NOT NULL DEFAULT 0 CHECK(total_score BETWEEN 0 AND 128),PRIMARY KEY(round_id,principal_id),FOREIGN KEY(round_id,series_id) REFERENCES bo3_rounds(id,series_id),FOREIGN KEY(series_id,principal_id) REFERENCES bo3_players(series_id,principal_id),CHECK(lease_expires_at=last_heartbeat_at+interval '45 seconds'));
CREATE TABLE bo3_guesses(round_id uuid NOT NULL,principal_id uuid NOT NULL,dataset_version text NOT NULL,driver_id text NOT NULL,attempt_number integer NOT NULL CHECK(attempt_number BETWEEN 1 AND 8),attributes jsonb NOT NULL,is_correct boolean NOT NULL,score integer NOT NULL CHECK(score BETWEEN 0 AND 16),event_seq integer NOT NULL CHECK(event_seq>0),accepted_at timestamptz NOT NULL,PRIMARY KEY(round_id,principal_id,attempt_number),UNIQUE(round_id,principal_id,driver_id),FOREIGN KEY(round_id,principal_id) REFERENCES bo3_round_players(round_id,principal_id),FOREIGN KEY(round_id,dataset_version) REFERENCES bo3_rounds(id,dataset_version),FOREIGN KEY(driver_id,dataset_version) REFERENCES driver_stats(driver_id,dataset_version));
CREATE TABLE bo3_events(series_id uuid NOT NULL REFERENCES bo3_series(id),seq integer NOT NULL CHECK(seq>0),round_id uuid REFERENCES bo3_rounds(id),kind text NOT NULL CHECK(kind IN ('start','heartbeat','guess','result','finish')),effective_at timestamptz NOT NULL,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),payload jsonb NOT NULL,PRIMARY KEY(series_id,seq));
CREATE UNIQUE INDEX bo3_one_result ON bo3_events(round_id) WHERE kind='result';
CREATE UNIQUE INDEX bo3_one_finish ON bo3_events(series_id) WHERE kind='finish';
CREATE TABLE bo3_requests(principal_id uuid NOT NULL REFERENCES identity_principals(id),idempotency_key uuid NOT NULL,digest text NOT NULL CHECK(digest~'^[a-f0-9]{64}$'),response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(principal_id,idempotency_key));
