ALTER TABLE points_ledger ADD COLUMN bo3_series_id uuid;
ALTER TABLE points_ledger ADD CONSTRAINT points_bo3_player_fk FOREIGN KEY(bo3_series_id,principal_id) REFERENCES bo3_players(series_id,principal_id);
