CREATE FUNCTION bo3_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_TABLE_NAME='bo3_series' THEN
  IF TG_OP='UPDATE' AND (OLD.status='finished' OR ROW(NEW.contract,NEW.difficulty,NEW.dataset_version,NEW.comparison_rules_version,NEW.starts_at,NEW.commitment,NEW.sealed_seed,NEW.seed_context,NEW.algorithm_version,NEW.answer_driver_ids) IS DISTINCT FROM ROW(OLD.contract,OLD.difficulty,OLD.dataset_version,OLD.comparison_rules_version,OLD.starts_at,OLD.commitment,OLD.sealed_seed,OLD.seed_context,OLD.algorithm_version,OLD.answer_driver_ids)) THEN RAISE EXCEPTION 'immutable BO3 series'; END IF;
  IF (SELECT count(DISTINCT x) FROM unnest(NEW.answer_driver_ids) x)<>7 THEN RAISE EXCEPTION 'seven distinct BO3 answers required'; END IF;
 ELSE
  IF OLD.status='revealed' OR ROW(NEW.series_id,NEW.round_number,NEW.answer_driver_id,NEW.dataset_version,NEW.starts_at,NEW.deadline_at) IS DISTINCT FROM ROW(OLD.series_id,OLD.round_number,OLD.answer_driver_id,OLD.dataset_version,OLD.starts_at,OLD.deadline_at) THEN RAISE EXCEPTION 'immutable BO3 round'; END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER bo3_series_immutable BEFORE INSERT OR UPDATE ON bo3_series FOR EACH ROW EXECUTE FUNCTION bo3_immutable();
CREATE TRIGGER bo3_round_immutable BEFORE UPDATE ON bo3_rounds FOR EACH ROW EXECUTE FUNCTION bo3_immutable();
